local s_vsh = [[
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif // GL_FRAGMENT_PRECISION_HIGH

attribute vec3 position;
attribute vec2 uv0;

uniform vec3 lightDirection;
uniform vec3 cameraPos;
uniform mat4 matWorld;
uniform mat4 matVP;
uniform mat4 matLH;
uniform mat4 matLD;
varying vec2 textureCoord;
varying vec3 worldNormal;
varying vec3 cameraDir;
varying vec3 lightDir;

void main()
{
    textureCoord = uv0;
    vec4 worldPosition = (matWorld * vec4(position, 1.0));
    lightDir = (matLD * matLH * vec4(lightDirection, 0.0)).xyz;
    cameraDir = worldPosition.xyz - cameraPos;
    worldNormal = (matWorld * vec4(position, 0.0)).xyz;
    gl_Position = matVP * worldPosition;
}
]]

local s_fsh = [[
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif // GL_FRAGMENT_PRECISION_HIGH

uniform float lightIntensity;
uniform vec3 lightColor;
uniform vec3 ambientColor;
uniform sampler2D inputImageTexture;
varying vec2 textureCoord;
varying vec3 worldNormal;
varying vec3 cameraDir;
varying vec3 lightDir;

void main() {
    vec4 texColor = texture2D(inputImageTexture, textureCoord);
    vec3 N = normalize(worldNormal);
    vec3 V = normalize(cameraDir);
    vec3 L = normalize(lightDir);
    vec3 H = normalize(V + L);
    float ndl = max(dot(N, L), 0.0);
    vec3 diffuse = texColor.rgb * ndl * lightColor * lightIntensity;
    float PI_DIV = 1.0 / 3.1415926;
	vec3 ambient = ambientColor * texColor.rgb;
    
	vec3 RLightDir = reflect(normalize(L), N);
	vec3 specular = pow(max(dot(RLightDir, V), 0.0), 32.0) * lightColor * lightIntensity * PI_DIV;

    gl_FragColor = vec4(diffuse + ambient + specular, texColor.a);
}
]]

