function CCSphere:createShpere(longitude, latitude)
    local PI = math.pi
    local PI_2 = PI * 2.0
    local PI_DIV2 = PI * 0.5
    local angleLongitude
	local angleLatitude = -PI_DIV2
	local segmentLongitude = PI_2/longitude
	local segmentLatitude = PI/(latitude-1)
	local x, y, z, projectxz
    local vertices = {}
    local texcoords = {}
    local verIndex = 1
    local uvIndex = 1
    for i=0, latitude, 1 do
        angleLongitude = 0.0
        for j=0, longitude, 1 do
            y = self.radius * math.sin(angleLatitude)
            projectxz = self.radius * math.cos(angleLatitude)
            x = projectxz * math.cos(angleLongitude)
            z = projectxz * math.sin(angleLongitude)
            
            vertices[verIndex] = x
            verIndex = verIndex + 1
            vertices[verIndex] = y
            verIndex = verIndex + 1
            vertices[verIndex] = z
            verIndex = verIndex + 1

            texcoords[uvIndex] = 1.0 - j / longitude - 0.25
            uvIndex = uvIndex + 1
            texcoords[uvIndex] = i / latitude
            uvIndex = uvIndex + 1

            angleLongitude = angleLongitude + segmentLongitude
        end
        angleLatitude = angleLatitude + segmentLatitude;
    end

    local indices = {}
    local index = 1
    for i=0, latitude - 1, 1 do
        for j=0, longitude, 1 do
            if j == longitude - 1 then
                indices[index] = i * longitude + j
                index = index + 1
                indices[index] = (i + 1) * longitude + j
                index = index + 1
                indices[index] = (i + 1) * longitude
                index = index + 1
                indices[index] = i * longitude + j
                index = index + 1
                indices[index] = (i + 1) * longitude
                index = index + 1
                indices[index] = i * longitude
                index = index + 1
            else
                indices[index] = i * longitude + j
                index = index + 1
                indices[index] = (i + 1) * longitude + j
                index = index + 1
                indices[index] = (i + 1) * longitude + j + 1
                index = index + 1
                indices[index] = i * longitude + j
                index = index + 1
                indices[index] = (i + 1) * longitude + j + 1
                index = index + 1
                indices[index] = i * longitude + j + 1
                index = index + 1
            end
        end
    end
    self.indexCount = #indices

    glDeleteBuffers(3, {self.vertexBuffer, self.uvBuffer, self.indexBuffer})

    local buffer = {}
    glGenBuffers(3,buffer)
    self.vertexBuffer = buffer[1]
    self.uvBuffer = buffer[2]
    self.indexBuffer = buffer[3]

    local verticesData = CGE.FloatBuffer:alloc(#vertices)
    verticesData:put(#vertices, vertices, 0)
    glBindBuffer(GL_ARRAY_BUFFER, self.vertexBuffer)
    glBufferData(GL_ARRAY_BUFFER, #vertices, verticesData, GL_STATIC_DRAW)

    local uvData = CGE.FloatBuffer:alloc(#texcoords)
    uvData:put(#texcoords, texcoords, 0)
    glBindBuffer(GL_ARRAY_BUFFER, self.uvBuffer)
    glBufferData(GL_ARRAY_BUFFER, #texcoords, uvData, GL_STATIC_DRAW)

    local indicesData = CGE.ShortBuffer:alloc(#indices)
    indicesData:put(#indices, indices, 0)
    glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, self.indexBuffer)
    glBufferDataS(GL_ELEMENT_ARRAY_BUFFER, #indices, indicesData, GL_STATIC_DRAW)
end

